css:
.p22-page { display: grid; grid-template-rows: auto 1fr; min-height: 100cqh; overflow-x: clip; }
.p22-page > .deck { grid-row: 2; align-self: center; }
.p22-top { display: grid; gap: var(--s-2); width: 100%; max-width: 56rem; margin-inline: auto; padding: var(--s-3) var(--s-3) 0; grid-row: 1; }
.p22-top:empty { display: none; }
.p22-strip { --p22-sh: 9rem; }
.p22-strip--b { --p22-sh: 4.5rem; }
.p22-strip .deck { --card: max(var(--card-min), min(var(--card-max), calc(100cqw - 2rem), calc(100cqh - 2rem - var(--peek) - var(--s-3) - var(--controls-h) - var(--p22-sh)))); }
@media not all and (min-width: 48rem) and (min-height: 31.25rem) { .p22-strip { --p22-sh: 17rem; } .p22-strip--b { --p22-sh: 6rem; } }
@media (max-width: 21.25rem) { .p22-strip { --p22-sh: 22rem; } .p22-strip--b { --p22-sh: 7rem; } }
.p22-win .deck-card__head { margin-top: 0; }
.p22-face { gap: var(--s-2); }
.p22-body { flex: 1 1 auto; min-height: 0; overflow: auto; display: grid; grid-auto-rows: min-content; gap: var(--s-3); align-content: start; padding-block: var(--s-1) var(--s-2); border-bottom: var(--w1) solid var(--rule); }
.p22-msg { flex: none; display: grid; gap: var(--s-2); }
.p22-msg:empty { display: none; }
.p22-foot { flex: none; display: grid; grid-auto-flow: column; grid-auto-columns: minmax(0, 1fr); gap: var(--s-2); }
.dialog__foot.p22-foot2 { display: grid; grid-auto-flow: column; grid-auto-columns: minmax(0, 1fr); }
.p22-focus { border-color: var(--blue); outline: var(--w1) solid var(--blue); outline-offset: calc(var(--w1) * -1); }
.p22-area { position: relative; }
.p22-count { position: absolute; right: var(--s-2); bottom: var(--s-1); font-size: var(--fs-cap); line-height: var(--lh-cap); color: var(--muted); pointer-events: none; background: var(--white); padding-inline: var(--s-1); }
.p22-count.is-over { color: var(--ink); font-weight: var(--fw-bold); }
.textarea.p22-ta { min-height: 4rem; padding-bottom: 1.375rem; resize: none; }
.p22-pair { display: grid; grid-template-columns: repeat(auto-fit, minmax(9.5rem, 1fr)); gap: var(--s-3); align-items: start; }
.p22-pair .field { grid-template-columns: minmax(0, 1fr); }
.p22-pair .select { height: auto; min-width: 0; padding-block: var(--s-2); }
.p22-pair .select > span { min-width: 0; flex: 1 1 auto; overflow: hidden; overflow-wrap: anywhere; }
.p22-pair .select .motive { display: flex; max-width: 100%; }
.p22-pair + .menu { margin-top: calc(var(--s-2) * -1); }
.p22-full { grid-column: 1 / -1; }
.textarea.p22-name { min-height: var(--ctl-h); padding: var(--s-2) var(--s-3); resize: none; overflow-wrap: anywhere; }
.btn .spinner { width: var(--icon-sm); height: var(--icon-sm); }
.p22-tipw { position: relative; display: flex; min-width: 0; }
.p22-tipw > .btn { flex: 1 1 auto; width: 100%; }
.p22-tip { position: absolute; z-index: 30; bottom: calc(100% + var(--s-1)); right: 0; width: max-content; max-width: min(17.5rem, 80vw); }
.p22-win .hint { font-size: var(--fs-small); }
.p22-fade { opacity: 0.5; }
.p22-pressed { border-width: var(--w2); border-color: var(--ink); text-decoration: underline; text-underline-offset: 0.25em; }

.dialog.p22-dlg { max-height: 100%; }
.dialog__foot.p22-foot3 { flex-direction: column; }
.dialog__foot.p22-foot3 > * { flex: none; }
.p22-dlg .dialog__body p + p { color: var(--muted); }
.p22-dlg .banner { padding-inline: var(--s-3); }
.p22-dlg .dialog__foot .p22-tipw { position: relative; }
.p22-dtip { position: absolute; z-index: 30; bottom: calc(100% + var(--s-1)); right: 0; width: max-content; max-width: min(17.5rem, 80vw); }

.p-menuwrap { position: relative; display: flex; }
.ibtn.is-open { border: var(--w2) solid var(--ink); }
.p22-menu { position: absolute; z-index: 30; right: 0; top: calc(100% + var(--s-1)); min-width: 12rem; max-width: calc(100cqw - var(--s-5)); }
.p22-menu .menu__item { min-height: var(--row-h); }


.p22-scroll { position: relative; }
.p22-scroll--end { display: flex; flex-direction: column; justify-content: flex-end; }
.p22-scroll--end > * { flex: none; }

.p22-scroll--field > .rec { display: none; }
.p22-scroll--field > .p22-newf { margin-top: 0; }
.p22-scroll--field .p22-ta { display: block; height: 2.625rem; min-height: 0; padding-block: var(--s-2); }
.p22-scroll--field .field { gap: 0; }
.p22-scroll--field .p22-btns { margin-top: var(--s-1); }
.deck-card .rec.p22-c { grid-template-columns: minmax(0, 1fr) auto; grid-template-areas: "title actions" "sub actions"; row-gap: 0; }
.deck-card .rec.p22-c .rec__lead, .deck-card .rec.p22-c .rec__value { display: none; }
.deck-card .rec.p22-c .rec__title { grid-area: title; font-weight: var(--fw-regular); }
.deck-card .rec.p22-c .rec__sub { grid-area: sub; align-self: start; }
.deck-card .rec.p22-c .rec__actions { grid-area: actions; grid-row: 1 / span 2; justify-self: end; align-self: center; flex-wrap: nowrap; }
@container card (max-width: 24rem) {
  .deck-card .rec.p22-c { grid-template-columns: minmax(0, 1fr); grid-template-areas: "title" "sub" "actions"; }
  .deck-card .rec.p22-c .rec__actions { grid-row: auto; }
}
.p22-hint { color: var(--muted); max-width: var(--measure); padding-block: var(--s-1); }
.p22-plus { display: flex; align-items: center; gap: var(--s-3); }
.p22-plus p { font-size: var(--fs-small); line-height: var(--lh-small); max-width: var(--measure); }
.p22-newf { margin-top: var(--s-2); }
.p22-btns { display: flex; gap: var(--s-2); margin-top: var(--s-2); }
.p22-btns .btn { flex: 0 1 auto; }
.p22-tipa { position: absolute; z-index: 30; width: max-content; max-width: 14rem; right: var(--s-1); }
.p22-area textarea { resize: none; }
.p22-ring { outline: var(--focus-ring); outline-offset: var(--focus-offset); }
.deck-card__scroll > .p22-newf { margin-top: var(--s-3); }

@media (max-width: 21.25rem) {
  .composer { gap: var(--s-1); padding-inline: var(--s-1); }
  .composer .input { padding-inline: var(--s-1); }
  .composer .input::placeholder { font-size: var(--fs-small); }
}

@media not all and (min-width: 48rem) and (min-height: 31.25rem) {
  .deck:has(.deck__flip:checked) .deck__layer, .deck:has(.deck__flip:checked) .deck__controls { display: none; }
  .deck:has(.deck__flip:checked) .deck__stack { width: min(var(--card-max), calc(100cqw - 2rem)); height: auto; }
  .deck:has(.deck__flip:checked) .deck-card { position: relative; left: auto; bottom: auto; height: auto; min-height: var(--card); max-height: calc(100cqh - 2rem - var(--p22-win-off, 0rem)); display: flex; flex-direction: column; }
  .deck:has(.deck__flip:checked) .deck-card__face--back { position: relative; inset: auto; flex: 1 1 auto; min-height: 0; }

  @container content (max-height: 18.75rem) {
    .deck:has(.deck__flip:checked) .deck-card { max-height: none; }
    .deck:has(.deck__flip:checked) .deck-card__scroll { overflow: visible; }
    .deck:has(.deck__flip:checked) .deck-card__back-foot { position: sticky; bottom: 0; z-index: 2; padding-block: var(--s-2); background: var(--mc); }
  }
}
.p22-strip { --p22-win-off: 9.5rem; }
@media not all and (min-width: 48rem) and (min-height: 31.25rem) { .p22-strip { --p22-win-off: 19.5rem; } }
@media (max-width: 21.25rem) { .p22-strip { --p22-win-off: 29.5rem; } }
.p22-strip.p22-strip--b { --p22-win-off: 5.5rem; }
@media (max-width: 21.25rem) { .p22-strip.p22-strip--b { --p22-win-off: 8rem; } }

.p22-dlg .dialog__foot:has(.p22-tipw) { display: grid; grid-template-columns: 1fr 1fr; }
.p22-dlg .dialog__foot .p22-tipw { display: contents; }
.p22-dlg .dialog__foot .p22-tipw > .tip { position: static; translate: none; width: auto; max-width: none; grid-column: 1 / -1; grid-row: 2; text-align: start; }

@media not all and (min-width: 48rem) and (min-height: 31.25rem) {
  .p22-dlg .dialog__head { flex-wrap: wrap; }
  .p22-dlg .dialog__head > .ibtn { order: -1; margin-inline-start: auto; }
  .p22-dlg .dialog__title { flex: 1 1 100%; }
}
@media (max-width: 21.25rem) { .scrim { padding: var(--s-3); } }

.p22-count { position: static; display: block; text-align: right; padding: 0; background: none; pointer-events: auto; }
.p22-area { display: grid; gap: var(--s-1); }
.p22-ta { padding-bottom: var(--s-2); }
.p22-draft { font-size: var(--fs-cap); line-height: var(--lh-cap); color: var(--muted); }

.mcard .deck-card__back-foot { background: transparent; }
.mcard .hint { color: var(--ink); }
.mcard .p22-hint { color: var(--ink); }
